        next: 'decide',
      },
      {
        id: 'decide', type: 'condition',
        condition: { outputField: { nodeId: 'flaky', path: 'attempt' }, operator: 'eq', value: 2 },
        then: 'yes', else: 'no',
      },
      { id: 'yes', type: 'end', result: 'yes' },
      { id: 'no', type: 'end', result: 'no' },
