      {
        id: 'decide', type: 'condition',
        condition: { outputField: { nodeId: 'risk.check', path: 'score' }, operator: 'eq', value: 1 },
        then: 'yes', else: 'no',
      },
      { id: 'yes', type: 'end', result: 'yes' },
      { id: 'no', type: 'end', result: 'no' },
    ],
  };
